// Autonomously generated by an AI agent.
#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <limits>
#include <vector>

#include "track/beatfactory.h"
namespace {
const auto kRate = mixxx::audio::SampleRate(44100);

TEST(BeatGridModeTest, RejectsMalformedBeatSequences) {
    for (const auto mode : {mixxx::BeatGridMode::Auto,
                 mixxx::BeatGridMode::Constant,
                 mixxx::BeatGridMode::Variable}) {
        for (const QVector<mixxx::audio::FramePos>& positions :
                {QVector<mixxx::audio::FramePos>{
                         mixxx::audio::FramePos(100), mixxx::audio::FramePos(100)},
                        QVector<mixxx::audio::FramePos>{
                                mixxx::audio::FramePos(100), mixxx::audio::FramePos(90)},
                        QVector<mixxx::audio::FramePos>{mixxx::audio::FramePos(100),
                                mixxx::audio::FramePos(std::numeric_limits<double>::infinity())}}) {
            EXPECT_FALSE(BeatFactory::makePreferredBeats(positions, {}, mode, kRate));
        }
    }
}
TEST(BeatGridModeTest, AutoRetainsSustainedTempoChangesAndManualOverride) {
    QVector<mixxx::audio::FramePos> positions;
    double time = 0.2;
    for (int i = 0; i < 160; ++i) {
        positions.push_back(mixxx::audio::FramePos(std::round(time * 50) * 882));
        time += 60.0 / (i < 80 ? 120 : 128);
    }
    const auto automatic =
            BeatFactory::makePreferredBeats(positions, {}, mixxx::BeatGridMode::Auto, kRate);
    const auto forced =
            BeatFactory::makePreferredBeats(positions, {}, mixxx::BeatGridMode::Constant, kRate);
    ASSERT_TRUE(automatic);
    ASSERT_TRUE(forced);
    EXPECT_FALSE(automatic->hasConstantTempo());
    EXPECT_TRUE(forced->hasConstantTempo());
}

TEST(BeatGridModeTest, ShortQuantizedConstantTracksRemainConstant) {
    for (const int rate : {44100, 48000}) {
        for (const int count : {32, 48, 96}) {
            for (const double bpm : {80.0, 132.06, 174.0, 210.0}) {
                SCOPED_TRACE(testing::Message()
                        << rate << " Hz, " << count << " beats, " << bpm << " BPM");
                QVector<mixxx::audio::FramePos> positions;
                for (int i = 0; i < count; ++i) {
                    positions.push_back(mixxx::audio::FramePos(
                            std::round((0.2 + i * 60 / bpm) * 50) / 50 * rate));
                }
                const auto grid = BeatFactory::makePreferredBeats(
                        positions, {}, mixxx::BeatGridMode::Auto, mixxx::audio::SampleRate(rate));
                ASSERT_TRUE(grid);
                EXPECT_TRUE(grid->hasConstantTempo());
                EXPECT_NEAR(bpm,
                        grid->getBpmInRange(positions.front(), positions.back()).value(),
                        0.15);
            }
        }
    }
}

TEST(BeatGridModeTest, TrackerPhaseStepsAndOffbeatSlipsDoNotImplyChangingTempo) {
    for (const double bpm : {120.0, 149.18}) {
        for (const bool permanent : {false, true}) {
            SCOPED_TRACE(testing::Message() << bpm << " BPM, permanent " << permanent);
            QVector<mixxx::audio::FramePos> positions;
            for (int i = 0; i < 1024; ++i) {
                const double phase = i >= 448 && (permanent || i < 576) ? 0.09 : 0;
                const double metricalSlip = i >= 192 && i < 256 ? 30 / bpm : 0;
                const double transition = (i >= 448 && i < 464) || (i >= 576 && i < 592)
                        ? 0.06 * std::sin(i * 0.7)
                        : 0;
                const double time =
                        std::round((0.2 + i * 60 / bpm + phase + metricalSlip + transition) * 50) /
                        50;
                positions.push_back(mixxx::audio::FramePos(time * kRate));
            }
            const auto automatic = BeatFactory::makePreferredBeats(
                    positions, {}, mixxx::BeatGridMode::Auto, kRate);
            ASSERT_TRUE(automatic);
            EXPECT_TRUE(automatic->hasConstantTempo());
            EXPECT_NEAR(bpm, automatic->getBpmAroundPosition(positions.front(), 1).value(), 0.03);
            const auto forced = BeatFactory::makePreferredBeats(
                    positions, {}, mixxx::BeatGridMode::Variable, kRate);
            ASSERT_TRUE(forced);
            EXPECT_FALSE(forced->hasConstantTempo());
        }
    }
}

TEST(BeatGridModeTest, SmoothTimingExcursionsAreJudgedByTheirSize) {
    for (const double amplitude : {0.02, 0.09}) {
        QVector<mixxx::audio::FramePos> positions;
        for (int i = 0; i < 1024; ++i) {
            const double time = 0.2 + i * 60 / 132.06 + amplitude * std::sin(M_PI * i / 1023);
            positions.push_back(mixxx::audio::FramePos(std::round(time * 50) / 50 * kRate));
        }
        const auto grid =
                BeatFactory::makePreferredBeats(positions, {}, mixxx::BeatGridMode::Auto, kRate);
        ASSERT_TRUE(grid);
        EXPECT_EQ(amplitude < 0.05, grid->hasConstantTempo());
    }
}

TEST(BeatGridModeTest, SustainedDriftAtTheEndMustNotBeTrimmedAsOutliers) {
    for (const double drift : {0.12, 0.4}) {
        QVector<mixxx::audio::FramePos> positions;
        for (int i = 0; i < 1024; ++i) {
            const double tail = std::max(0, i - 895) / 128.0;
            const double time = 0.2 + i * 0.5 + drift * tail;
            positions.push_back(mixxx::audio::FramePos(std::round(time * 50) / 50 * kRate));
        }
        const auto grid =
                BeatFactory::makePreferredBeats(positions, {}, mixxx::BeatGridMode::Auto, kRate);
        ASSERT_TRUE(grid);
        EXPECT_FALSE(grid->hasConstantTempo());
    }
}

TEST(BeatGridModeTest, SustainedMetricalTempoChangesAreNotOffbeatSlips) {
    for (const double secondBpm : {80.0, 240.0}) {
        for (const int changeBeat : {512, 896}) {
            SCOPED_TRACE(testing::Message() << secondBpm << " BPM at beat " << changeBeat);
            QVector<mixxx::audio::FramePos> positions;
            double time = 0.2;
            for (int i = 0; i < 1024; ++i) {
                positions.push_back(mixxx::audio::FramePos(std::round(time * 50) / 50 * kRate));
                time += 60.0 / (i < changeBeat ? 120 : secondBpm);
            }
            const auto grid = BeatFactory::makePreferredBeats(
                    positions, {}, mixxx::BeatGridMode::Auto, kRate);
            ASSERT_TRUE(grid);
            EXPECT_FALSE(grid->hasConstantTempo());
        }
    }
}

TEST(BeatGridModeTest, LocalTimingBiasMustNotAccumulateIntoConstantGridDrift) {
    for (const double bpm : {120.0, 132.06}) {
        for (const auto mode : {mixxx::BeatGridMode::Auto, mixxx::BeatGridMode::Constant}) {
            SCOPED_TRACE(testing::Message() << bpm << " BPM, mode " << static_cast<int>(mode));
            QVector<mixxx::audio::FramePos> positions;
            for (int i = 0; i < 2048; ++i) {
                const double timingBias = (i % 64) * 0.02 / 63;
                const double time = 0.2 + i * 60 / bpm + timingBias;
                positions.push_back(mixxx::audio::FramePos(std::round(time * 50) / 50 * kRate));
            }
            const auto grid = BeatFactory::makePreferredBeats(positions, {}, mode, kRate);
            ASSERT_TRUE(grid);
            EXPECT_TRUE(grid->hasConstantTempo());
            EXPECT_NEAR(
                    bpm, grid->getBpmInRange(positions.front(), positions.back()).value(), 0.01);
            for (const int start : {0, static_cast<int>(positions.size()) - 64}) {
                std::vector<double> errors;
                for (int i = start; i < start + 64; ++i) {
                    errors.push_back(
                            std::abs(grid->findClosestBeat(positions[i]) - positions[i]) / 44100.0);
                }
                std::sort(errors.begin(), errors.end());
                EXPECT_LT(errors[errors.size() / 2], 0.035);
            }
        }
    }
}

TEST(QuantizedBeatMapTest, QuantizedPositionsKeepAccuratePredominantBpm) {
    for (const int sampleRate : {44100, 48000}) {
        for (const double bpm : {133.15, 138.0}) {
            SCOPED_TRACE(testing::Message() << sampleRate << " Hz, " << bpm << " BPM");
            QVector<mixxx::audio::FramePos> positions;
            for (int i = 0; i < 512; ++i) {
                const double time = std::round((0.2 + i * 60 / bpm) * 50) / 50;
                positions.push_back(mixxx::audio::FramePos(std::round(time * sampleRate)));
            }
            const auto grid = mixxx::Beats::fromBeatPositions(
                    mixxx::audio::SampleRate(sampleRate), positions);
            ASSERT_TRUE(grid);
            EXPECT_NEAR(
                    bpm, grid->getBpmInRange(positions.front(), positions.back()).value(), 0.25);
        }
    }
}

} // namespace
